/**
 * The Sonar page backdrop (/datasets and in-app /sonar): dotted mountain
 * ranges and a faint perspective grid floor under the Sonar stage.
 *
 * Oct 31: mountains replace the large dotted world map, which repeated the
 * dotted globe already at the centre of the stage. Same treatment: a dot
 * pattern in a token colour drawn through a mask (orbital-map.css,
 * .dsi-mountains), so the dots take the emerald from the theme. The mask is
 * public/images/datasets/mountains-bg.svg, generated by
 * scripts/gen-sonar-mountains.mjs. The ranges dip in the middle, behind the
 * stage. Decorative: aria-hidden.
 *
 * Replaces the looping globe video (public/videos/datasets-globe.mp4), which
 * nothing else uses.
 */
export default function GlobeBackground() {
  return (
    <div className="dsi-backdrop" aria-hidden="true">
      <div className="dsi-mountains" />
      <div className="dsi-floor" />
    </div>
  );
}
